CHECKPOINT = None  # caller must supply a newly captured, verified release checkpoint
# Exact previously accepted Docker archive member size, independently pinned in
# continue-manifest-bound-pair.py; never weaken the hash/size identity checks.
INNER_BYTES = 204488782
TIMERS = ['v79-g2-approved-task-worker.timer','v79-workforce-evening.timer','v79-workforce-morning.timer']
ROOT = Path('/home/firelion/.v79-hardened-pair-releases')
SSH = ['ssh','-T','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes',
       '-o','ConnectTimeout=10','firelion@192.168.100.163']


class Refused(ValueError):pass


def need(ok,reason):
    if not ok:raise Refused(reason)


def sha(path):
    with Path(path).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()


def private_file(path,limit=16*1024**2):
    info=Path(path).lstat()
    need(stat.S_ISREG(info.st_mode) and info.st_nlink==1 and info.st_uid==os.geteuid()
         and not info.st_mode&0o077 and info.st_size<=limit,'PRIVATE_FILE_UNSAFE')
    return Path(path).read_bytes()


def write_new(path,value):
    raw=value if isinstance(value,bytes) else json.dumps(value,sort_keys=True).encode()
    fd=os.open(path,os.O_CREAT|os.O_EXCL|os.O_WRONLY|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    fd=os.open(Path(path).parent,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(fd)
    finally:os.close(fd)


def module(name,root=None):
    root=Path(root) if root else Path(__file__).resolve().parent
    path=root/(name+'.py');spec=importlib.util.spec_from_file_location(name.replace('-','_'),path)
    m=importlib.util.module_from_spec(spec);sys.modules[spec.name]=m;spec.loader.exec_module(m);return m


def call(args,*,data=None,timeout=120):
    try:p=subprocess.run(args,input=data,capture_output=True,timeout=timeout)
    except (OSError,subprocess.TimeoutExpired):raise Refused('COMMAND_OR_MONITOR_UNAVAILABLE') from None
    if p.returncode:
        # Preserve only our remote runner's structured safe refusal. Raw SSH,
        # Docker and application output must never become an error message.
        try:
            error=json.loads(p.stdout)
            if error.get('status')=='BLOCKED' and isinstance(error.get('reason'),str):
                reason=safe_reason(Refused(error['reason']))
                if reason!='RELEASE_BLOCKED_REDACTED':raise Refused('REMOTE_'+reason)
        except Refused:raise
        except (ValueError,AttributeError):pass
        raise Refused('COMMAND_FAILED_REDACTED')
    return p.stdout


def timestamp(value):
    result=datetime.datetime.fromisoformat(value)
    need(result.tzinfo is not None,'CHECKPOINT_TIMESTAMP_INVALID');return result


def fresh(backup):
    now=datetime.datetime.now(datetime.timezone.utc)
    age=(now-timestamp(backup['created_at'])).total_seconds()
    need(0<=age<=4*3600,'CHECKPOINT_OUTSIDE_FOUR_HOUR_RELEASE_WINDOW')
    need(timestamp(backup['verified_at'])>=timestamp(backup['created_at']), 'CUSTODY_TIMESTAMP_INVALID')


def custody(home):
    checkpoint=Path(home)/'V79-Portfolio-Checkpoints'/CHECKPOINT
    raw=private_file(checkpoint/'manifest.json',2*1024**2);manifest=json.loads(raw)
    need(manifest.get('audit')=='V79_RELEASE_WINDOW_CHECKPOINT_V1'
         and manifest.get('apps_resumed_same_ids') is True
         and manifest.get('recipient_fingerprint')=='484CF39CE37A02884497AD9C41A17102D2842ECE'
         and len(manifest.get('files',[]))==15,'FRESH_CHECKPOINT_MANIFEST_INVALID')
    expected={'protected-images.tar.gpg','runtime-and-config.tar.gpg','private-host-state.tar.gpg',
              'tiquet-postgres.dump.gpg','v79-hub-postgres.dump.gpg'}
    expected.update(n+'-mount-'+str(i)+'.tar.gpg' for n,count in
        [('v79-hub',7),('v79-tiquet-manager',2),('v79-business-agent',1)] for i in range(count))
    need({f.get('name') for f in manifest['files']}==expected,'CHECKPOINT_ARTIFACT_SCOPE_INVALID')
    for entry in manifest['files']:
        path=checkpoint/entry['name'];info=path.lstat()
        need(stat.S_ISREG(info.st_mode) and not path.is_symlink() and info.st_uid==os.geteuid()
             and not info.st_mode&0o077 and info.st_size==entry['bytes'],'CHECKPOINT_ARTIFACT_UNAVAILABLE')
    matches=[]
    for path in checkpoint.glob('offhost-verified-*.json'):
        receipt_raw=private_file(path,2*1024**2);receipt=json.loads(receipt_raw)
        if receipt.get('manifest_sha256')==hashlib.sha256(raw).hexdigest():matches.append((receipt,path))
    need(len(matches)==1,'EXACT_CUSTODY_RECEIPT_REQUIRED')
    receipt,path=matches[0]
    need(receipt.get('audit')=='V79_RELEASE_WINDOW_OFFHOST_CUSTODY_V1'
         and len(receipt.get('files',[]))==15
         and {f.get('name') for f in receipt['files']}==expected
         and all(isinstance(f.get('plaintext_bytes'),int) and f['plaintext_bytes']>0
                 and re.fullmatch('[0-9a-f]{64}',f.get('plaintext_sha256',''))
                 for f in receipt['files']),'OFFHOST_DECRYPT_CUSTODY_INCOMPLETE')
    backup={'checkpoint':CHECKPOINT,'created_at':manifest['created_at'],
        'verified_at':receipt['verified_at'],'manifest_sha256':hashlib.sha256(raw).hexdigest(),
        'custody_sha256':sha(path),'images':manifest['images']}
    fresh(backup);return backup


def server_root():
    root=Path(__file__).resolve().parent
    need(socket.gethostname()=='v79sl' and os.geteuid()!=0 and Path.home()==Path('/home/firelion'),
         'RUN_SERVER_ON_NONROOT_V79SL_ONLY')
    need(root.parent==ROOT and re.fullmatch(r'pair-[0-9]{8}T[0-9]{6}Z-[0-9a-f]{12}',root.name),
         'PRIVATE_RELEASE_PATH_INVALID')
    os.umask(0o077)
    info=root.lstat()
    need(stat.S_ISDIR(info.st_mode) and info.st_uid==os.geteuid()
         and stat.S_IMODE(info.st_mode)==0o700,'PRIVATE_RELEASE_DIRECTORY_UNSAFE')
    for filename,source in SOURCES.items():
        need(private_file(root/filename)==source.encode(),'RELEASE_MODULE_CHANGED')
    fd=module('paired-release-context',root).private_directory(root);os.close(fd)
    need(not os.environ.get('DOCKER_HOST') and not os.environ.get('DOCKER_CONTEXT'),'DOCKER_OVERRIDE_REFUSED')
    ctx=json.loads(call(['docker','context','inspect']))
    need(len(ctx)==1 and ctx[0]['Endpoints']['docker']['Host'] in
         ('unix:///var/run/docker.sock','unix:///run/docker.sock'),'DOCKER_NOT_LOCAL')
    need(call(['docker','info','--format','{{.Name}}']).decode().strip()=='v79sl','DOCKER_DAEMON_HOST_MISMATCH')
    return root


@contextlib.contextmanager
def release_lock():
    handles=[]
    try:
        for name in ('.v79-portfolio-rollout.lock','.v79-p1-logout-live-release.lock'):
            path=Path.home()/name
            if name=='.v79-p1-logout-live-release.lock' and not path.exists():continue
            fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
            info=os.fstat(fd);need(stat.S_ISREG(info.st_mode) and info.st_uid==os.geteuid(),'RELEASE_LOCK_UNSAFE')
            handles.append(fd)
            try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:raise Refused('OTHER_RELEASE_OPERATION_RUNNING') from None
        yield
    finally:
        for fd in handles:os.close(fd)


def remote_backup(backup):
    fresh(backup)
    need(backup['checkpoint']==CHECKPOINT,'UNAPPROVED_CHECKPOINT')
    path=Path.home()/'.v79-release-checkpoints'/CHECKPOINT/'checkpoint/manifest.json'
    raw=private_file(path,2*1024**2)
    need(hashlib.sha256(raw).hexdigest()==backup['manifest_sha256'],'REMOTE_CHECKPOINT_MANIFEST_CHANGED')
    need(json.loads(raw)['images']==backup['images'],'CHECKPOINT_IMAGE_IDENTITIES_CHANGED')


def prepare(payload,root):
    review=module('review-hardened-release',root);transaction=module('paired-compose-transaction',root)
    remote_backup(payload['backup'])
    # Read-only private-app HTTP gate before any archive transfer or restart.
    local_health_pair()
    need(hashlib.sha256(payload['helper'].encode()).hexdigest()==review.HELPER_SHA,'EXISTING_HELPER_CHECKSUM_CHANGED')
    ns={'__name__':'readonly_helpers'};exec(compile(payload['helper'],'<verified-helper>','exec'),ns)
    need(payload['backup']['images']==ns['PINS'],'BACKUP_DOES_NOT_MATCH_CURRENT_PINNED_RELEASE')
    snapshots={}
    def render(args,directory,extra,overlay):
        p=subprocess.run([*args,'-f','-','config','--format','json'],input=json.dumps(overlay).encode(),
            capture_output=True,cwd=directory,env={**os.environ,**extra},timeout=60)
        need(p.returncode==0,'IMAGE_ONLY_MODEL_RENDER_FAILED')
        result=json.loads(p.stdout)
        for name,spec in overlay['services'].items():
            item=snapshots.setdefault(name,{'directory':directory})
            which='candidate' if spec['image']=='sha256:'+review.EXPECTED[name][0] else 'rollback'
            item[which]=result
        return result
    accepted=review.review(payload,ns,render)
    # The trusted helper's output protocol is JSON-only; use our bounded reader
    # for the plain-text name listing and never print inspect/config output.
    names=call(['docker','ps','--all','--format','{{.Names}}']).decode().splitlines()
    rows={r['Name'].lstrip('/'):r for r in json.loads(call(['docker','inspect',*names]))}
    for name,image in ns['PINS'].items():
        row=rows[name]
        need(row['Image']==image and row['State'].get('Running')
             and row['State'].get('Health',{}).get('Status')=='healthy','CORE_CHANGED_AFTER_MODEL_REVIEW')
    for name in review.EXPECTED:
        row=rows[name]
        fingerprint=ns['digest']({'Config':row['Config'],'HostConfig':row['HostConfig'],
            'Mounts':row.get('Mounts'),'Networks':sorted(row.get('NetworkSettings',{}).get('Networks',{}))})
        need(fingerprint==review.RUNTIME_FINGERPRINTS[name],'ACCEPTED_APP_CHANGED_AFTER_REVIEW')
    version=call(['docker','compose','version','--short']).decode().strip().removeprefix('v')
    info=json.loads(call(['docker','info','--format','{{json .SecurityOptions}}']))
    plan={'schema':'v79-hardened-image-only-transaction-v1','backup':payload['backup'],
        'apps':{},'protected':{n:r for n,r in rows.items() if n not in review.EXPECTED},
        'selinux_enabled':any('selinux' in value.lower() for value in info),'timers':TIMERS,
        'source_sha256':sha(Path(__file__)),'requires_supervision':True}
    for name in review.EXPECTED:
        baseline=rows[name];labels=baseline['Config']['Labels'];snap=snapshots[name]
        entry={'baseline':baseline,'directory':snap['directory'],'project':labels['com.docker.compose.project'],
            'service':labels['com.docker.compose.service'],'compose_version':version,
            'candidate_image':payload['configs'][name],
            'rollback_image':json.loads(call(['docker','image','inspect',baseline['Image']]))[0],
            'model':snap['candidate'],
            'removed_metadata':accepted['apps'][name]['image_defaults']['reviewed_removed_base_metadata_names']}
        for which in ('candidate','rollback'):
            path=root/(name+'-'+which+'.json');write_new(path,snap[which])
            entry[which+'_file']=str(path);entry[which+'_sha256']=sha(path)
            args=['docker','compose','--env-file','/dev/null','--project-name',entry['project'],
                  '--project-directory',entry['directory'],'-f',str(path),'config','--format','json']
            need(json.loads(call(args))==snap[which],'SEALED_MODEL_ROUNDTRIP_CHANGED')
        plan['apps'][name]=entry
    pin=transaction.seal_plan(root,plan)
    backend=transaction.ComposeBackend(root,plan);backend.protected();backend.check_files()
    # Require both original working containers to be unchanged after writing.
    for name,entry in plan['apps'].items():
        need(transaction.protected_fingerprint(backend.inspect(name))==
             transaction.protected_fingerprint(entry['baseline']),'APP_CHANGED_DURING_PREPARATION')
    return {'status':'PASS_DURABLE_PLAN_PREPARED_NO_IMAGES_LOADED','release_directory':str(root),
            'plan_sha256':pin,'source_sha256':sha(Path(__file__)),'release_decision':'HOLD'}


def validate_plan(root,pin):
    transaction=module('paired-compose-transaction',root);plan=transaction.load_plan(root,pin)
    contract=module('paired-image-release-contract',root)
    need(plan.get('schema')=='v79-hardened-image-only-transaction-v1'
         and plan.get('source_sha256')==sha(Path(__file__)) and set(plan['apps'])==set(contract.CURRENT)
         and plan['timers']==TIMERS and plan.get('requires_supervision') is True,'PRIVATE_PLAN_SCOPE_CHANGED')
    for name,entry in plan['apps'].items():
        need(entry['service']==name and entry['rollback_image']['Id']==contract.CURRENT[name]
             and entry['candidate_image']['Id']==contract.CANDIDATE[name],'PRIVATE_PLAN_IMAGE_SCOPE_CHANGED')
    backend=transaction.ComposeBackend(root,plan);backend.check_files();return transaction,plan,backend


def timers_stop():
    for timer in TIMERS:
        need(call(['systemctl','--user','is-active',timer]).decode().strip()=='active','ORIGINAL_TIMER_STATE_CHANGED')
    call(['systemctl','--user','stop',*TIMERS])
    deadline=time.monotonic()+120
    while time.monotonic()<deadline:
        units=['v79-g2-approved-task-worker.service','v79-workforce-briefing@morning.service',
               'v79-workforce-briefing@evening.service']
        busy=[call(['systemctl','--user','show',unit,'--value','-p','ActiveState']).decode().strip() for unit in units]
        if not any(v in ('active','activating','deactivating','reloading') for v in busy):return
        time.sleep(2)
    raise Refused('WORKFORCE_JOB_DID_NOT_DRAIN')


def timers_resume():
    call(['systemctl','--user','start',*TIMERS])
    for timer in TIMERS:need(call(['systemctl','--user','is-active',timer]).decode().strip()=='active','TIMER_RESUME_NOT_VERIFIED')


def local_health_pair():
    """Require HTTP200+exact status inside each private app network namespace.

    Neither production app publishes its HTTP port on the host. The verified
    previous host-loopback probe would therefore falsely fail after cutover.
    Use a read-only Node fetch from the selected running container instead.
    No port changes, external calls, host publishing or secret output.
    """
    script=r"""
const target=process.argv[1], expected=process.argv[2];
const stop=new AbortController();
const timeout=setTimeout(()=>stop.abort(),10000);
try {
  const response=await fetch(target,{signal:stop.signal,redirect:'error'});
  if (response.status!==200) process.exitCode=2;
  else {
    const raw=await response.text();
    if (raw.length>65536 || JSON.parse(raw).status!==expected) process.exitCode=2;
  }
} catch {process.exitCode=2;}
finally {clearTimeout(timeout);}
"""
    for container,url,status in (
        ('v79-hub','http://127.0.0.1:3040/api/health','ok'),
        ('v79-tiquet-manager','http://127.0.0.1:3050/health','healthy')):
        try:
            output=subprocess.run(['docker','exec',container,'node','--input-type=module',
                                   '-e',script,url,status],
                stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=25)
        except (OSError,subprocess.TimeoutExpired):
            raise Refused('SELECTED_PRIVATE_HTTP_HEALTH_UNAVAILABLE') from None
        need(output.returncode==0,'SELECTED_PRIVATE_HTTP_HEALTH_FAILED')


def execute(root,pin,manual=False):
    transaction,plan,backend=validate_plan(root,pin)
    if not manual:
        deadline=time.monotonic()+20
        while True:
            try:backend.supervised();break
            except transaction.Refused:
                need(time.monotonic()<deadline,'OWNER_MONITOR_HEARTBEAT_REQUIRED')
                time.sleep(1)
        remote_backup(plan['backup']);backend.protected()
        for name,entry in plan['apps'].items():
            row=backend.inspect(name)
            need(transaction.protected_fingerprint(row)==transaction.protected_fingerprint(entry['baseline']),
                 'ORIGINAL_APP_CHANGED_SINCE_PREPARATION')
            image=json.loads(call(['docker','image','inspect',entry['candidate_image']['Id']]))[0]
            need(image['Id']==entry['candidate_image']['Id'] and
                 (image['Config'].get('Labels') or {}).get('org.opencontainers.image.revision')==
                 module('paired-image-release-contract',root).REVISIONS[name],
                 'LOADED_IMAGE_IDENTITY_OR_SOURCE_CHANGED')
        profiles=transaction.stopped_profiles(backend)
        need(profiles['profiles_verified']==4,'COMPLETE_CANDIDATE_ROLLBACK_PROFILE_PROOF_REQUIRED')
        print(json.dumps(profiles),flush=True)
    import signal
    def interrupted(*_):raise Refused('SUPERVISED_TRANSACTION_INTERRUPTED')
    signal.signal(signal.SIGTERM,interrupted);signal.signal(signal.SIGINT,interrupted)
    safe_to_resume=False;paused=False
    try:
        backend.journal('TIMERS_PAUSE_INTENT');paused=True
        if manual:call(['systemctl','--user','stop',*TIMERS])
        else:timers_stop()
        result=transaction.rollback(backend,list(plan['apps'])) if manual else transaction.deploy(backend)
        if manual or result.get('candidate_deployment_failed'):
            for name,entry in plan['apps'].items():
                row=backend.inspect(name)
                if row['Id']==entry['baseline']['Id']:
                    need(transaction.protected_fingerprint(row)==transaction.protected_fingerprint(entry['baseline'])
                         and row['State'].get('Health',{}).get('Status')=='healthy',
                         'UNTOUCHED_ORIGINAL_APP_CHANGED_DURING_ROLLBACK')
                else:backend.healthy(name,'rollback')
        try:local_health_pair()
        except Refused:
            if manual or result.get('candidate_deployment_failed'):raise
            result=transaction.rollback(backend,list(plan['apps']))
            result['candidate_deployment_failed']=True
            result['candidate_failure_reason']='SELECTED_HTTP_HEALTH_FAILED'
            local_health_pair()
        safe_to_resume=True
        result['apps']={}
        for name,entry in plan['apps'].items():
            row=backend.inspect(name)
            result['apps'][name]={'image':row['Image'],'container_id':row['Id'],
                'health':row['State'].get('Health',{}).get('Status'),
                'runtime_config_fingerprint':transaction.digest({'Config':row['Config'],
                    'HostConfig':row['HostConfig'],'Mounts':row.get('Mounts'),
                    'Networks':sorted(row.get('NetworkSettings',{}).get('Networks',{}))})}
        result['checkpoint_manifest_sha256']=plan['backup']['manifest_sha256']
        result['application_data_restored']=False
        result['protected_core_identity_and_health_unchanged']=True
        result['local_http_health_pair']=True
        result['application_rollback_executed']=bool(manual or result.get('candidate_deployment_failed'))
        return result
    finally:
        if paused and safe_to_resume:timers_resume()
        elif paused:backend.journal('TIMERS_HELD_OPERATOR_REVIEW_REQUIRED')


def server_main(args):
    root=server_root()
    with release_lock():
        if args.server_prepare:
            result=prepare(json.loads(sys.stdin.buffer.read(512*1024)),root)
        elif args.server_load:
            need(bool(args.plan_sha256),'IMAGE_LOAD_REQUIRES_SEALED_RELEASE_PLAN')
            _,plan,_=validate_plan(root,args.plan_sha256);remote_backup(plan['backup'])
            path=root/'accepted-images.tar.gz'
            fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
            h=hashlib.sha256();total=0
            with os.fdopen(fd,'wb') as f:
                while True:
                    block=sys.stdin.buffer.read(1024**2)
                    if not block:break
                    total+=len(block);need(total<=INNER_BYTES,'TRANSFER_TOO_LARGE');h.update(block);f.write(block)
                f.flush();os.fsync(f.fileno())
            need(total==INNER_BYTES,'TRANSFER_SIZE_MISMATCH')
            need(h.hexdigest()==args.server_load,'ACCEPTED_IMAGE_TRANSFER_HASH_MISMATCH')
            call(['docker','image','load','--input',str(path)],timeout=900)
            result={'status':'PASS_IMAGE_TRANSFER_LOAD_ONLY','release_decision':'HOLD'}
        else:
            try:
                result=execute(root,args.server_rollback or args.server_execute,manual=bool(args.server_rollback))
            except BaseException as error:
                result={'status':'BLOCKED','reason':safe_reason(error),'release_decision':'HOLD'}
            if args.server_rollback:
                import secrets
                out=root/('rollback-outcome-'+secrets.token_hex(6)+'.json')
            else:out=root/'outcome.json'
            write_new(out,result)
        print(json.dumps(result),flush=True)


def safe_reason(error):
    return (str(error) if type(error).__name__ in ('Refused','Stop')
            and re.fullmatch('[A-Z][A-Za-z0-9_:,.]+',str(error)) else 'RELEASE_BLOCKED_REDACTED')


def remote_directory(value):
    path=Path(value)
    need(path.parent==ROOT and re.fullmatch(r'pair-[0-9]{8}T[0-9]{6}Z-[0-9a-f]{12}',path.name),
         'REMOTE_RELEASE_DIRECTORY_INVALID')
    return path


def monitor(root):
    root=remote_directory(str(root))
    probe="""import json
import os,time,stat,secrets
from pathlib import Path
r=Path(ROOT_VALUE)
lease=r/'supervision.json'
if lease.exists() or lease.is_symlink():
 s=lease.lstat();assert stat.S_ISREG(s.st_mode) and s.st_uid==os.geteuid() and s.st_nlink==1 and not s.st_mode&0o077
temporary=r/('.supervision-'+secrets.token_hex(8))
fd=os.open(temporary,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
with os.fdopen(fd,'wb') as f:
 f.write(json.dumps({'monotonic':time.monotonic()}).encode());f.flush();os.fsync(f.fileno())
os.replace(temporary,lease)
p=r/'outcome.json';j=r/'events.jsonl';e=r/'exit-code'
events=j.read_text().splitlines() if j.is_file() else []
last=json.loads(events[-1]) if events else {}
print(json.dumps({'outcome':json.loads(p.read_text()) if p.is_file() else None,
 'event':last,'exit':e.read_text().strip() if e.is_file() else None}))
""".replace('ROOT_VALUE',repr(str(root)))
    print('MONITORING_RELEASE='+str(root),flush=True)
    last=None;deadline=time.monotonic()+40*60
    while True:
        raw=call([*SSH,'python3 -c '+shlex.quote(probe)])
        observation=json.loads(raw);result=observation['outcome'];event=observation['event']
        if event!=last and event:
            need(re.fullmatch('[A-Z_]+',event.get('event',''))
                 and event.get('app') in (None,'v79-hub','v79-tiquet-manager'),'MONITOR_EVENT_INVALID')
            print('RELEASE_EVENT='+event['event']+(('_'+event['app']) if event.get('app') else ''),flush=True);last=event
        if result is not None:print(json.dumps(result,indent=2),flush=True);return result
        need(observation['exit'] is None,'RUNNER_EXITED_WITHOUT_RECEIPT_USE_SAVED_ROLLBACK_POINTER')
        need(time.monotonic()<deadline,'MONITOR_WINDOW_ENDED_DO_NOT_RELAUNCH_CHECK_SAVED_POINTER')
        time.sleep(5)


def client_main(args):
    need(socket.gethostname()=='firelion-Aspire-A315-51' and os.geteuid()!=0,'RUN_ON_ACER_ONLY')
    os.umask(0o077)
    if args.monitor:return monitor(args.monitor)
    client=Path(tempfile.mkdtemp(prefix='v79-hardpair-client-',dir=Path.home()))
    for filename,source in SOURCES.items():write_new(client/filename,source.encode())
    review=module('review-hardened-release',client)
    payload=review.archive_payload(Path.home()/'Downloads/hardened-pair-candidate.zip',
        Path.home()/'Downloads/Vision79_Tiquet_Parity_ReadOnly_bceb8f08.py')
    payload['backup']=custody(Path.home())
    # Install source only in a new private release directory; no application or
    # image operation can run during bootstrap. SSH protects the payload in flight.
    source=Path(__file__).read_text()
    bootstrap=r'''import datetime,hashlib,json,os,secrets,socket,stat,sys
from pathlib import Path
assert socket.gethostname()=='v79sl' and os.geteuid()!=0 and Path.home()==Path('/home/firelion')
os.umask(0o077);p=json.load(sys.stdin);root=Path.home()/'.v79-hardened-pair-releases'
if not root.exists():root.mkdir(mode=0o700)
s=root.lstat();assert stat.S_ISDIR(s.st_mode) and s.st_uid==os.geteuid() and stat.S_IMODE(s.st_mode)==0o700
run=root/('pair-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+secrets.token_hex(6));run.mkdir(mode=0o700)
assert len(p['files'])<=8 and sum(len(v['content']) for v in p['files'].values())<1024*1024
for name,item in p['files'].items():
 assert Path(name).name==name and name.endswith('.py') and hashlib.sha256(item['content'].encode()).hexdigest()==item['sha256']
 fd=os.open(run/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'wb') as f:f.write(item['content'].encode());f.flush();os.fsync(f.fileno())
print(str(run))
'''
    files={**SOURCES,'release-hardened-pair.py':source}
    package={'files':{name:{'content':value,'sha256':hashlib.sha256(value.encode()).hexdigest()}
                      for name,value in files.items()}}
    root=remote_directory(call([*SSH,'python3 -c '+shlex.quote(bootstrap)],
        data=json.dumps(package).encode()).decode().strip())
    command=shlex.join(['python3','-u',str(root/'release-hardened-pair.py'),'--server-prepare',
                          '--checkpoint-name',CHECKPOINT])
    prepared=json.loads(call([*SSH,command],data=json.dumps(payload).encode(),timeout=300))
    need(prepared.get('status')=='PASS_DURABLE_PLAN_PREPARED_NO_IMAGES_LOADED','DURABLE_PREPARATION_BLOCKED')
    write_new(client/'release-pointer.json',prepared)
    print(json.dumps(prepared,indent=2),flush=True)
    print('ACER_RELEASE_POINTER='+str(client/'release-pointer.json'),flush=True)
    print('MANUAL_ROLLBACK_COMMAND='+shlex.join(['ssh','-o','StrictHostKeyChecking=yes',
        'firelion@192.168.100.163',shlex.join(['python3',str(root/'release-hardened-pair.py'),
        '--server-rollback',prepared['plan_sha256'],'--checkpoint-name',CHECKPOINT])]),flush=True)
    if not args.deploy:return
    archive=Path.home()/'Downloads/hardened-pair-candidate.zip'
    with archive.open('rb') as archive_file,zipfile.ZipFile(archive_file) as z:
        need(z.getinfo('patched-pair.docker.tar.gz').file_size==INNER_BYTES,
             'ACCEPTED_INNER_IMAGE_ARCHIVE_SIZE_CHANGED')
        archive_file.seek(0)
        need(hashlib.file_digest(archive_file,'sha256').hexdigest()==review.ARCHIVE_SHA,
             'ACCEPTED_ARCHIVE_CHANGED_BEFORE_TRANSFER')
        h=hashlib.sha256()
        with z.open('patched-pair.docker.tar.gz') as stream:
            for block in iter(lambda:stream.read(1024**2),b''):h.update(block)
        command=shlex.join(['python3',str(root/'release-hardened-pair.py'),'--server-load',h.hexdigest(),
                           '--plan-sha256',prepared['plan_sha256'],'--checkpoint-name',CHECKPOINT])
        with z.open('patched-pair.docker.tar.gz') as stream:
            process=subprocess.Popen([*SSH,command],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL)
            try:
                for block in iter(lambda:stream.read(1024**2),b''):process.stdin.write(block)
                process.stdin.close();process.stdin=None
                raw,_=process.communicate(timeout=1200)
                if process.returncode:
                    # Only remote structured, sanitized refusal codes may escape;
                    # never forward raw Docker/SSH stderr or application output.
                    try:report=json.loads(raw)
                    except (ValueError,TypeError):report={}
                    reason=report.get('reason') if report.get('status')=='BLOCKED' else None
                    if isinstance(reason,str) and re.fullmatch(r'[A-Z][A-Z0-9_]{0,96}',reason):
                        raise Refused('IMAGE_TRANSFER_'+reason)
                    raise Refused('IMAGE_TRANSFER_OR_LOAD_FAILED')
                need(json.loads(raw).get('status')=='PASS_IMAGE_TRANSFER_LOAD_ONLY','IMAGE_LOAD_NOT_VERIFIED')
            finally:
                if process.poll() is None:process.kill()
                process.wait()
    print('ACCEPTED_IMAGE_TRANSFER_AND_LOAD=PASS',flush=True)
    worker=['python3','-u',str(root/'release-hardened-pair.py'),'--server-execute',prepared['plan_sha256'],
            '--checkpoint-name',CHECKPOINT]
    wrapper=("import os,subprocess;from pathlib import Path;p=subprocess.run("+repr(worker)+
        ");fd=os.open("+repr(str(root/'exit-code'))+",os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600);"
        "os.write(fd,str(p.returncode).encode());os.fsync(fd);os.close(fd)")
    launch=shlex.join(['python3','-u','-c',wrapper])
    call([*SSH,'umask 077; nohup '+launch+' > '+shlex.quote(str(root/'progress.log'))+' 2>&1 < /dev/null &'])
    print('TRANSACTION=DETACHED_SUPERVISED_MONITOR',flush=True)
    return monitor(root)


def main():
    p=argparse.ArgumentParser(description=__doc__)
    modes=p.add_mutually_exclusive_group(required=True)
    modes.add_argument('--prepare',action='store_true');modes.add_argument('--deploy',action='store_true')
    modes.add_argument('--monitor')
    modes.add_argument('--server-prepare',action='store_true');modes.add_argument('--server-load')
    modes.add_argument('--server-execute');modes.add_argument('--server-rollback')
    p.add_argument('--plan-sha256')
    p.add_argument('--checkpoint-name')
    args=p.parse_args()
    global CHECKPOINT
    need(isinstance(args.checkpoint_name,str) and bool(re.fullmatch(
         r'release-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}',args.checkpoint_name)),
         'FRESH_EXPLICIT_CHECKPOINT_NAME_REQUIRED')
    CHECKPOINT=args.checkpoint_name
    if args.server_prepare or args.server_load or args.server_execute or args.server_rollback:server_main(args)
    else:client_main(args)


if __name__=='__main__':
    try:main()
    except BaseException as error:
        if isinstance(error,SystemExit):raise
        reason=safe_reason(error)
        print(json.dumps({'status':'BLOCKED','reason':reason,'release_decision':'HOLD'}),flush=True)
        raise SystemExit(2)
